with base as (select id, order_id, quantity, unit_price * quantity as line_total from order_items where product_id is not null) select id, order_id, lag(line_total) over w_grp as prev_line_total, lead(line_total) over w_grp as next_line_total, lead(quantity) over w_grp as next_quantity, row_number() over w_grp as row_seq, sum(line_total) over w_running as cumulative_line_total from base window w_grp as (partition by order_id order by quantity, id), w_running as (partition by order_id order by quantity, id rows between unbounded preceding and current row);
